app.post('/api/projects',userOnly,asyncRoute(async(req,res)=>{
  const repo=parseRepo(req.body.repository||'');const name=String(req.body.name||'').trim(),token=String(req.body.githubToken||process.env.GITHUB_TOKEN||'');
  if(!repo)return res.status(400).json({error:'Enter a valid github.com/owner/repository URL.'});if(!name)return res.status(400).json({error:'Enter a project name.'});
  const client=new Octokit({...token?{auth:token}:{},userAgent:'Orbit-Project-Intelligence/1.0'});let r;try{r=token?(await client.repos.get(repo)).data:await publicGitInfo(repo.owner,repo.repo)}catch(e){if(!token)return res.status(400).json({error:`Could not access that public GitHub repository without using the GitHub API. Check the URL, make sure Git is installed, and confirm the repository is public. Details: ${e.message}`});throw e}
  const secret=crypto.randomBytes(32).toString('hex');let p;
  try{const out=await pool.query("INSERT INTO projects(owner_id,name,description,repo_owner,repo_name,default_branch,encrypted_token,webhook_secret,index_status) VALUES($1,$2,$3,$4,$5,$6,$7,$8,'indexing') RETURNING id,name,description,repo_owner,repo_name,default_branch,last_indexed_at,last_commit_sha,created_at,index_status,index_error",[req.session.userId,name,String(req.body.description||''),r.owner.login,r.name,r.default_branch,token?encrypt(token):null,encrypt(secret)]);p=out.rows[0]}catch(e){if(e.code==='23505')return res.status(409).json({error:'This repository is already connected to your account.'});throw e}
  res.status(202).json({project:p,indexing:true});
  setImmediate(async()=>{const job={...p,encrypted_token:token?encrypt(token):null,webhook_secret:secret,owner_id:req.session.userId};try{await syncProject(job);const base=process.env.APP_URL||`http://localhost:${PORT}`;let webhook='polling fallback';if(token&&/^https:\/\//i.test(base)){try{const hook=await client.repos.createWebhook({...repo,config:{url:`${base}/api/github/webhook/${p.id}`,content_type:'json',secret,insecure_ssl:'0'},events:['push'],active:true});await pool.query('UPDATE projects SET webhook_id=$2 WHERE id=$1',[p.id,hook.data.id]);webhook='webhook active'}catch(err){console.warn('Could not install GitHub webhook; polling remains active:',err.message)}}console.log(`Indexed ${repo.owner}/${repo.repo} (${webhook})`)}catch(err){console.error('Initial indexing failed:',err);await markIndexError(job,err)}});
}));
